initJs:
function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.実行日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  renderHistoryRows(tables[0]?.records || []);

  // 全店舗選択チェックボックスの処理
  const storeAllCheckbox = container.querySelector("#store-all");
  const storeCheckboxes = container.querySelectorAll(".store-checkbox");

  storeAllCheckbox.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // モデル選択時のパラメータ表示
  const modelSelect = container.querySelector("#model-select");
  const parametersDiv = container.querySelector("#model-parameters");

  modelSelect.addEventListener("change", function() {
    const modelParams = {
      "model-v1.0": `
アルゴリズム: Random Forest
特徴量数: 25
学習データ期間: 2022/01/01 - 2023/12/31
ハイパーパラメータ:
  - n_estimators: 100
  - max_depth: 10
  - min_samples_split: 5
      `,
      "model-v1.1": `
アルゴリズム: XGBoost
特徴量数: 30
学習データ期間: 2022/06/01 - 2024/05/31
ハイパーパラメータ:
  - learning_rate: 0.1
  - max_depth: 6
  - n_estimators: 200
      `,
      "model-v2.0": `
アルゴリズム: LSTM Neural Network
特徴量数: 35
学習データ期間: 2023/01/01 - 2024/06/30
ハイパーパラメータ:
  - hidden_units: 128
  - dropout_rate: 0.2
  - learning_rate: 0.001
      `
    };

    parametersDiv.innerHTML = this.value ? 
      `<pre style="color: var(--text); margin: 0;">${modelParams[this.value] || ""}</pre>` :
      '<div class="muted">モデルを選択してください</div>';
  });

  // テスト実行ボタンの処理
  const executeBtn = container.querySelector("#btn-test-execute");
  const testResults = container.querySelector("#test-results");
  const testProgress = container.querySelector("#test-progress");
  const progressBar = container.querySelector("#progress-bar");
  const progressText = container.querySelector("#progress-text");

  executeBtn.addEventListener("click", async function() {
    // バリデーション
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#category-select").value;
    const selectedStores = Array.from(container.querySelectorAll(".store-checkbox:checked"));
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!model) {
      alert("予測モデルが選択されていません");
      return;
    }
    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return;
    }
    if (new Date(endDate) < new Date(startDate)) {
      alert("終了日は開始日より後の日付を設定してください");
      return;
    }
    if (selectedStores.length === 0 && !storeAllCheckbox.checked) {
      alert("店舗が選択されていません");
      return;
    }
    if (!category) {
      alert("商品カテゴリが未選択です");
      return;
    }
    if (!selectedDataset) {
      alert("テストデータセットが選択されていません");
      return;
    }

    // テスト実行開始
    testResults.classList.add("hidden");
    testProgress.classList.remove("hidden");
    executeBtn.disabled = true;

    // プログレスバーのアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 95) progress = 95;
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.floor(progress) + "%";
    }, 500);

    // 模擬テスト実行（実際の処理時間をシミュレート）
    await new Promise(resolve => setTimeout(resolve, 3000));

    // プログレス完了
    clearInterval(progressInterval);
    progressBar.style.width = "100%";
    progressText.textContent = "100%";

    await new Promise(resolve => setTimeout(resolve, 500));

    // 結果表示
    testProgress.classList.add("hidden");
    testResults.classList.remove("hidden");
    executeBtn.disabled = false;

    // 模擬結果データ
    const mapeValue = (Math.random() * 15 + 5).toFixed(2);
    const rmseValue = (Math.random() * 50 + 20).toFixed(2);
    const r2Value = (Math.random() * 0.3 + 0.7).toFixed(3);
    const executionTime = (Math.random() * 120 + 30).toFixed(0);

    container.querySelector("#mape-value").textContent = mapeValue + "%";
    container.querySelector("#rmse-value").textContent = rmseValue;
    container.querySelector("#r2-value").textContent = r2Value;
    container.querySelector("#execution-time").textContent = executionTime + "秒";

    // グラフ描画
    drawComparisonChart();

    // テスト履歴に追加
    const historyData = {
      実行日時: new Date().toLocaleString("ja-JP"),
      モデル名: model,
      テスト期間: `${startDate} - ${endDate}`,
      対象店舗数: storeAllCheckbox.checked ? "全店舗" : selectedStores.length,
      MAPE: mapeValue + "%",
      RMSE: rmseValue,
      実行時間: executionTime + "秒"
    };

    const saved = await window.aivicApi.save(0, historyData);
    if (saved) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderHistoryRows(rows);
    }
  });

  // グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 模擬データ生成
    const days = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.2) * 20;
      actualData.push(base + (Math.random() - 0.5) * 30);
      predictedData.push(base + (Math.random() - 0.5) * 20);
    }

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    const maxValue = Math.max(...actualData, ...predictedData);
    const minValue = Math.min(...actualData, ...predictedData);
    const valueRange = maxValue - minValue;

    // 実績値線
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線
    ctx.strokeStyle = '#ff6a4a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillStyle = '#4a9eff';
    ctx.fillRect(padding, padding - 30, 15, 3);

    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 120, padding - 20);
    ctx.fillStyle = '#ff6a4a';
    ctx.fillRect(padding + 100, padding - 30, 15, 3);
  }

  // エクスポートボタンの処理
  const exportBtn = container.querySelector("#btn-export-results");
  exportBtn.addEventListener("click", function() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const mape = container.querySelector("#mape-value").textContent;
    const rmse = container.querySelector("#rmse-value").textContent;
    const r2 = container.querySelector("#r2-value").textContent;
    const execTime = container.querySelector("#execution-time").textContent;

    const csvContent = [
      '\uFEFF', // BOM
      'テスト実行結果レポート\n',
      `実行日時,${new Date().toLocaleString("ja-JP")}\n`,
      `モデル名,${model}\n`,
      `テスト期間,${startDate} - ${endDate}\n`,
      `MAPE,${mape}\n`,
      `RMSE,${rmse}\n`,
      `決定係数(R²),${r2}\n`,
      `実行時間,${execTime}\n`
    ].join('');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderHistoryRows(rows);
      return;
    }

    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      alert("詳細表示機能は開発中です");
      return;
    }
  });

  // 最新データの読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderHistoryRows(rows);
  });
}
